const content={dua:{title:'দোয়া শিখি, অর্থ বুঝি',description:'দৈনন্দিন জীবনের দোয়াগুলো আরবি পাঠ, বাংলা অর্থ এবং কখন পড়তে হয়—এই তিনটি দিক মিলিয়ে শেখার পরিকল্পনা। উচ্চারণ ও সূত্র যাচাইকে আমরা গুরুত্ব দিই।'},quran:{title:'আয়াতের শিক্ষা, জীবনের ভাবনা',description:'কুরআনের আয়াতের অর্থ ও স্বীকৃত তাফসিরের আলোকে সহজ আলোচনা আমাদের পরিকল্পনার অংশ। উদ্দেশ্য—শিক্ষাগুলো বুঝতে এবং দৈনন্দিন জীবনের সঙ্গে মিলিয়ে ভাবতে সাহায্য করা।'},adab:{title:'সুন্দর ব্যবহার থেকেই শুরু',description:'পরিবার, প্রতিবেশী ও সমাজের মানুষের সঙ্গে ভালো আচরণ, কথায় সংযম এবং দায়িত্বশীল জীবনযাপন—এই বিভাগের আলোচনার বিষয়। ছোট ছোট ভালো অভ্যাস গড়তে চাই একসাথে।'},seerah:{title:'আদর্শ জীবন থেকে শেখা',description:'নবীজি ﷺ-এর জীবনের নির্ভরযোগ্য বর্ণনা থেকে সততা, দয়া, ধৈর্য ও সুন্দর আচরণের শিক্ষা তুলে ধরার পরিকল্পনা। ঘটনা ও তার সূত্র যাচাইকে এখানে বিশেষ গুরুত্ব দেওয়া হবে।'}};
document.querySelectorAll('[data-topic]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-topic]').forEach(item=>{item.classList.toggle('active',item===button);item.setAttribute('aria-pressed',String(item===button))});const item=content[button.dataset.topic];document.getElementById('topic-title').textContent=item.title;document.getElementById('topic-description').textContent=item.description}));
const menu=document.querySelector('.menu'),nav=document.getElementById('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'মেনু বন্ধ করুন':'মেনু খুলুন');nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','মেনু খুলুন')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','মেনু খুলুন');menu.focus()}});
document.getElementById('year').textContent=new Date().getFullYear();
